<?php namespace App\Http\Controllers; use App\Models\{Product,Inventory,InventoryMovement}; use App\Services\InventoryService; use App\Enums\InventoryMovementType; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class InventoryController extends Controller {public function __construct(private InventoryService $service){} public function index(){ $branch=auth()->user()->branch_id;$items=Inventory::with('product')->where('branch_id',$branch)->paginate(20);$allItems=Inventory::with('product')->where('branch_id',$branch)->get();$lowStockItems=$allItems->filter(function($item){$available=max(0,$item->quantity-($item->reserved_quantity??0));return $available <= $item->product->minimum_stock;});return view('inventory.index',compact('items','lowStockItems'));} public function create(){return view('inventory.create',['mainCategories'=>\App\Models\Category::where('business_id',auth()->user()->business_id)->whereNull('parent_id')->orderBy('name')->get(),'subcategories'=>\App\Models\Category::where('business_id',auth()->user()->business_id)->whereNotNull('parent_id')->orderBy('name')->get()]);} public function store(Request $r){$validated=$r->validate(['name'=>'required|unique:products,name','sku'=>'nullable','barcode'=>'nullable|unique:products,barcode','category_id'=>'required|exists:categories,id','brand'=>'nullable','part_number'=>'nullable','cost_price'=>'nullable|numeric','selling_price'=>'required|numeric','minimum_stock'=>'required|integer','image'=>'nullable|image|max:2048']);if(empty($validated['sku'])){$validated['sku']='PRD-'.date('Y').'-'.str_pad((string)(Product::max('id')+1),6,'0',STR_PAD_LEFT);}$validated['business_id']=auth()->user()->business_id;if($r->hasFile('image')){$validated['image']=$r->file('image')->store('products','public');}$p=Product::create($validated);$this->service->adjust($p,auth()->user()->branch_id,(float)$r->input('opening_stock',0),'Opening stock',InventoryMovementType::PURCHASE->value);return redirect()->route('inventory.index')->with('success','Product created.');} public function edit(Product $product){return view('inventory.edit',['product'=>$product,'mainCategories'=>\App\Models\Category::where('business_id',auth()->user()->business_id)->whereNull('parent_id')->orderBy('name')->get(),'subcategories'=>\App\Models\Category::where('business_id',auth()->user()->business_id)->whereNotNull('parent_id')->orderBy('name')->get()]);} public function update(Request $r,Product $product){$validated=$r->validate(['name'=>'required','category_id'=>'required|exists:categories,id','brand'=>'nullable','part_number'=>'nullable','cost_price'=>'nullable|numeric','selling_price'=>'required|numeric','minimum_stock'=>'required|integer','image'=>'nullable|image|max:2048']);if($r->hasFile('image')){$validated['image']=$r->file('image')->store('products','public');}$product->update($validated);return redirect()->route('inventory.index')->with('success','Product updated.');} public function destroy(Product $product){try{return DB::transaction(function()use($product){\App\Models\Inventory::where('product_id',$product->id)->delete();\App\Models\InventoryMovement::where('product_id',$product->id)->delete();\App\Models\CustomerSuppliedPart::where('product_id',$product->id)->delete();\App\Models\EmergencyPurchase::where('product_id',$product->id)->delete();\App\Models\JobPart::where('product_id',$product->id)->delete();\App\Models\PurchaseOrderItem::where('product_id',$product->id)->delete();\App\Models\StockTransferItem::where('product_id',$product->id)->delete();\App\Models\Warranty::where('product_id',$product->id)->delete();$product->delete();return redirect()->route('inventory.index')->with('success','Product deleted.');});}catch(\Exception $e){return back()->with('error','Cannot delete product: '.$e->getMessage());}} public function adjust(Request $r,Product $product){$reason=$r->input('reason')?:'Manual adjustment';$quantity=(float)$r->validate(['quantity'=>'required|numeric'])['quantity'];$currentInventory=Inventory::where('product_id',$product->id)->where('branch_id',auth()->user()->branch_id)->first();$currentQty=$currentInventory?$currentInventory->quantity:0;if($currentQty+$quantity<0){return back()->with('error','Cannot reduce stock below zero. Current stock: '.$currentQty);}$this->service->adjust($product,auth()->user()->branch_id,$quantity,$reason);return back()->with('success','Stock adjusted.');}}
